package com.dropnest.nazifa;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.provider.MediaStore;import android.speech.*;import android.speech.tts.TextToSpeech;import android.webkit.*;import java.util.*;
public class MainActivity extends Activity implements RecognitionListener,TextToSpeech.OnInitListener{static final int FILE=1001,AUDIO=1002;WebView web;ValueCallback<Uri[]> callback;Uri cameraUri;SpeechRecognizer speech;TextToSpeech tts;@Override public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);web.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);web.setWebViewClient(new WebViewClient());web.addJavascriptInterface(new Bridge(),"AndroidBridge");web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){callback=cb;Intent docs=new Intent(Intent.ACTION_OPEN_DOCUMENT);docs.addCategory(Intent.CATEGORY_OPENABLE);docs.setType("*/*");docs.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);docs.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","application/pdf","text/plain"});Intent chooser=Intent.createChooser(docs,"Choose photos or files");if(p.isCaptureEnabled()){try{cameraUri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,new ContentValues());Intent cam=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);cam.putExtra(MediaStore.EXTRA_OUTPUT,cameraUri);chooser.putExtra(Intent.EXTRA_INITIAL_INTENTS,new Intent[]{cam});}catch(Exception ignored){}}startActivityForResult(chooser,FILE);return true;}});speech=SpeechRecognizer.createSpeechRecognizer(this);speech.setRecognitionListener(this);tts=new TextToSpeech(this,this);web.loadUrl("file:///android_asset/index.html");}class Bridge{@JavascriptInterface public void startVoice(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=23&&checkSelfPermission("android.permission.RECORD_AUDIO")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.RECORD_AUDIO"},AUDIO);return;}Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,Locale.getDefault());speech.startListening(i);});}@JavascriptInterface public void speak(String text){runOnUiThread(()->tts.speak(text,TextToSpeech.QUEUE_FLUSH,null,"nazifa"));}@JavascriptInterface public void shareUrl(String url,String title){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,url);startActivity(Intent.createChooser(i,title));}}@Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=FILE||callback==null)return;ArrayList<Uri> uris=new ArrayList<>();if(result==RESULT_OK){if(data!=null&&data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data!=null&&data.getData()!=null)uris.add(data.getData());else if(cameraUri!=null)uris.add(cameraUri);}callback.onReceiveValue(uris.isEmpty()?null:uris.toArray(new Uri[0]));callback=null;}void js(String fn,String value){web.evaluateJavascript(fn+"("+org.json.JSONObject.quote(value)+")",null);}@Override public void onResults(Bundle b){ArrayList<String>x=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(x!=null&&!x.isEmpty())js("window.onVoiceResult",x.get(0));}@Override public void onError(int e){js("window.onVoiceError","Voice input failed. Please try again.");}@Override public void onInit(int s){}public void onReadyForSpeech(Bundle b){}public void onBeginningOfSpeech(){}public void onRmsChanged(float f){}public void onBufferReceived(byte[]b){}public void onEndOfSpeech(){}public void onPartialResults(Bundle b){}public void onEvent(int t,Bundle b){}@Override protected void onDestroy(){speech.destroy();tts.shutdown();web.destroy();super.onDestroy();}}